CREATE TYPE "RequestStatus" AS ENUM ('PENDING','APPROVED','RESCHEDULED','REJECTED','PAID','CANCELLED');
CREATE TYPE "PaymentMethod" AS ENUM ('CASH','BANK_TRANSFER','CARD','OTHER');
CREATE TYPE "NotificationChannel" AS ENUM ('IN_APP','WHATSAPP','EMAIL');
CREATE TYPE "DeliveryStatus" AS ENUM ('QUEUED','SENT','DELIVERED','FAILED');
CREATE TABLE "AdminUser" ("id" TEXT PRIMARY KEY, "name" TEXT NOT NULL, "email" TEXT NOT NULL UNIQUE, "passwordHash" TEXT NOT NULL, "active" BOOLEAN NOT NULL DEFAULT true, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "Mall" ("id" TEXT PRIMARY KEY, "name" TEXT NOT NULL UNIQUE, "location" TEXT, "active" BOOLEAN NOT NULL DEFAULT true, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "Company" ("id" TEXT PRIMARY KEY, "name" TEXT NOT NULL, "contactName" TEXT, "phone" TEXT, "email" TEXT, "mallId" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Company_mallId_fkey" FOREIGN KEY ("mallId") REFERENCES "Mall"("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE UNIQUE INDEX "Company_name_mallId_key" ON "Company"("name","mallId"); CREATE INDEX "Company_mallId_name_idx" ON "Company"("mallId","name");
CREATE TABLE "CompanyToken" ("id" TEXT PRIMARY KEY, "tokenHash" TEXT NOT NULL UNIQUE, "companyId" TEXT NOT NULL, "expiresAt" TIMESTAMP(3), "revokedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "CompanyToken_companyId_fkey" FOREIGN KEY ("companyId") REFERENCES "Company"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE INDEX "CompanyToken_companyId_revokedAt_idx" ON "CompanyToken"("companyId","revokedAt");
CREATE TABLE "PaymentRequest" ("id" TEXT PRIMARY KEY, "reference" TEXT NOT NULL UNIQUE, "companyId" TEXT NOT NULL, "mallId" TEXT NOT NULL, "amount" DECIMAL(14,2) NOT NULL, "currency" TEXT NOT NULL DEFAULT 'IQD', "requestedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "dueAt" TIMESTAMP(3), "appointmentAt" TIMESTAMP(3), "status" "RequestStatus" NOT NULL DEFAULT 'PENDING', "note" TEXT, "representativeName" TEXT, "representativePhone" TEXT, "idempotencyKey" TEXT UNIQUE, "createdByCompanyTokenId" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "PaymentRequest_companyId_fkey" FOREIGN KEY ("companyId") REFERENCES "Company"("id") ON DELETE RESTRICT ON UPDATE CASCADE, CONSTRAINT "PaymentRequest_mallId_fkey" FOREIGN KEY ("mallId") REFERENCES "Mall"("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE INDEX "PaymentRequest_status_dueAt_idx" ON "PaymentRequest"("status","dueAt"); CREATE INDEX "PaymentRequest_mallId_requestedAt_idx" ON "PaymentRequest"("mallId","requestedAt"); CREATE INDEX "PaymentRequest_companyId_requestedAt_idx" ON "PaymentRequest"("companyId","requestedAt");
CREATE TABLE "Appointment" ("id" TEXT PRIMARY KEY, "companyId" TEXT NOT NULL, "requestId" TEXT, "scheduledAt" TIMESTAMP(3) NOT NULL, "status" TEXT NOT NULL DEFAULT 'SCHEDULED', "note" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Appointment_companyId_fkey" FOREIGN KEY ("companyId") REFERENCES "Company"("id") ON DELETE CASCADE ON UPDATE CASCADE, CONSTRAINT "Appointment_requestId_fkey" FOREIGN KEY ("requestId") REFERENCES "PaymentRequest"("id") ON DELETE SET NULL ON UPDATE CASCADE);
CREATE INDEX "Appointment_scheduledAt_status_idx" ON "Appointment"("scheduledAt","status"); CREATE INDEX "Appointment_companyId_scheduledAt_idx" ON "Appointment"("companyId","scheduledAt");
CREATE TABLE "Payment" ("id" TEXT PRIMARY KEY, "companyId" TEXT NOT NULL, "requestId" TEXT NOT NULL, "amount" DECIMAL(14,2) NOT NULL, "paidAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "method" "PaymentMethod" NOT NULL, "notes" TEXT, "adminId" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Payment_companyId_fkey" FOREIGN KEY ("companyId") REFERENCES "Company"("id") ON DELETE RESTRICT ON UPDATE CASCADE, CONSTRAINT "Payment_requestId_fkey" FOREIGN KEY ("requestId") REFERENCES "PaymentRequest"("id") ON DELETE RESTRICT ON UPDATE CASCADE, CONSTRAINT "Payment_adminId_fkey" FOREIGN KEY ("adminId") REFERENCES "AdminUser"("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE INDEX "Payment_companyId_paidAt_idx" ON "Payment"("companyId","paidAt"); CREATE INDEX "Payment_requestId_paidAt_idx" ON "Payment"("requestId","paidAt");
CREATE TABLE "Notification" ("id" TEXT PRIMARY KEY, "requestId" TEXT, "adminId" TEXT, "channel" "NotificationChannel" NOT NULL DEFAULT 'IN_APP', "deliveryStatus" "DeliveryStatus" NOT NULL DEFAULT 'QUEUED', "recipient" TEXT, "message" TEXT NOT NULL, "dedupeKey" TEXT NOT NULL UNIQUE, "attempts" INTEGER NOT NULL DEFAULT 0, "lastError" TEXT, "sentAt" TIMESTAMP(3), "deliveredAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Notification_requestId_fkey" FOREIGN KEY ("requestId") REFERENCES "PaymentRequest"("id") ON DELETE SET NULL ON UPDATE CASCADE, CONSTRAINT "Notification_adminId_fkey" FOREIGN KEY ("adminId") REFERENCES "AdminUser"("id") ON DELETE SET NULL ON UPDATE CASCADE);
CREATE INDEX "Notification_deliveryStatus_createdAt_idx" ON "Notification"("deliveryStatus","createdAt");
CREATE TABLE "AuditLog" ("id" TEXT PRIMARY KEY, "adminId" TEXT, "action" TEXT NOT NULL, "entityType" TEXT NOT NULL, "entityId" TEXT, "metadata" JSONB, "ipAddress" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "AuditLog_adminId_fkey" FOREIGN KEY ("adminId") REFERENCES "AdminUser"("id") ON DELETE SET NULL ON UPDATE CASCADE);
CREATE INDEX "AuditLog_entityType_entityId_createdAt_idx" ON "AuditLog"("entityType","entityId","createdAt"); CREATE INDEX "AuditLog_adminId_createdAt_idx" ON "AuditLog"("adminId","createdAt");
